cat > /tmp/ParseBinlog.cs << 'EOF'
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors
var errors = new List<(string Project, string Code, string File, int Line, string Message)>();

build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.File ?? "", error.LineNumber, error.Text ?? ""));
});

// Also collect warnings that might be relevant
var warnings = new List<(string Project, string Code, string Message)>();
build.VisitAllChildren<Warning>(w => {
    var project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    if (w.Code == "NU1101" || w.Code == "NU1102" || w.Code?.StartsWith("NU") == true)
        warnings.Add((project, w.Code ?? "", w.Text ?? ""));
});

Console.WriteLine("=== BUILD ERRORS ===");
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

foreach (var g in errors.GroupBy(e => e.Project)) {
    Console.WriteLine($"Project: {g.Key}");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.Code}] {e.File}({e.Line}): {e.Message}");
    }
    Console.WriteLine();
}

if (warnings.Any()) {
    Console.WriteLine("=== RELEVANT WARNINGS ===");
    foreach (var g in warnings.GroupBy(w => w.Project)) {
        Console.WriteLine($"Project: {g.Key}");
        foreach (var w in g) {
            Console.WriteLine($"  [{w.Code}] {w.Message}");
        }
        Console.WriteLine();
    }
}
EOF
