using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== ALL ERRORS & WARNINGS ===");
build.VisitAllChildren<AbstractDiagnostic>(d => {
    var project = "";
    var node = d.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    var kind = d is Error ? "ERROR" : "WARN";
    Console.WriteLine($"  [{kind}] [{d.Code}] {project} | {d.File}({d.LineNumber}): {d.Text}");
});

Console.WriteLine();
Console.WriteLine("=== PROJECT REFERENCES ===");
build.VisitAllChildren<Item>(item => {
    if (item.Name == "PackageReference" || item.Name == "ProjectReference") {
        var project = "";
        var node = item.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
