using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look at evaluation folder for Services to see what items were evaluated
Console.WriteLine("=== Evaluation items for Services (looking for PackageReference) ===");
build.VisitAllChildren<Folder>(f => {
    if (f.Name == "Items" || f.Name == "AddItem" || f.Name == "Evaluation") {
        var project = "";
        var p = f.Parent;
        while (p != null) {
            if (p is Project proj) { project = proj.Name; break; }
            p = p.Parent;
        }
        if (project.Contains("Services") && f.Name == "Items") {
            foreach (var child in f.Children) {
                var s = child.ToString();
                if (s.Contains("Package")) {
                    Console.WriteLine($"  {s}");
                    if (child is TreeNode tn) {
                        foreach (var gc in tn.Children.Take(10)) {
                            Console.WriteLine($"    {gc}");
                            if (gc is TreeNode tn2) {
                                foreach (var ggc in tn2.Children.Take(5)) {
                                    Console.WriteLine($"      {ggc}");
                                }
                            }
                        }
                    }
                }
            }
        }
    }
});

Console.WriteLine();
Console.WriteLine("=== NuGet restore log for Services ===");
int c = 0;
build.VisitAllChildren<Message>(m => {
    if (c > 20) return;
    var project = "";
    var p = m.Parent;
    while (p != null) {
        if (p is Project proj) { project = proj.Name; break; }
        p = p.Parent;
    }
    if (project.Contains("Services") && m.Text?.Contains("PackageReference") == true) {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
        c++;
    }
});
EOF
