using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Let's look at the project file content from the evaluation
// The binlog should have the evaluated project file embedded
Console.WriteLine("=== Looking for project file content ===");

// Try to find the source file content for UserService.cs
build.VisitAllChildren<SourceFile>(sf => {
    Console.WriteLine($"  SourceFile: {sf.Name}");
});

// Check for the project.assets.json or similar
Console.WriteLine();
Console.WriteLine("=== Checking resolved references for Services ===");
build.VisitAllChildren<Item>(item => {
    var project = "";
    var p = item.Parent;
    while (p != null) {
        if (p is Project proj) { project = proj.Name; break; }
        p = p.Parent;
    }
    if (project.Contains("Services") && (item.Name == "ReferencePath" || item.Name == "_ResolveAssemblyReferenceResolvedFiles")) {
        Console.WriteLine($"  [{item.Name}] {item.Text}");
    }
});

Console.WriteLine();
Console.WriteLine("=== Csc command line for Services ===");
int cscCount = 0;
build.VisitAllChildren<Task>(task => {
    if (cscCount > 0) return;
    if (task.Name == "Csc") {
        var project = "";
        var p = task.Parent;
        while (p != null) {
            if (p is Project proj) { project = proj.Name; break; }
            p = p.Parent;
        }
        if (project.Contains("Services")) {
            Console.WriteLine($"  Csc task in {project}");
            foreach (var child in task.Children.Take(5)) {
                var s = child.ToString();
                if (s.Contains("/reference") || s.Contains("Newtonsoft")) {
                    Console.WriteLine($"    {s.Substring(0, Math.Min(200, s.Length))}");
                }
            }
            cscCount++;
        }
    }
});
