using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look at the Csc task's CommandLineArguments
Console.WriteLine("=== Csc CommandLineArguments for Services ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var project = "";
        var p = task.Parent;
        while (p != null) {
            if (p is Project proj) { project = proj.Name; break; }
            p = p.Parent;
        }
        if (project.Contains("Services")) {
            task.VisitAllChildren<Property>(prop => {
                if (prop.Name == "CommandLineArguments") {
                    // Extract just /reference lines
                    foreach (var line in prop.Value.Split('\n')) {
                        if (line.Contains("/reference") || line.Contains("-reference")) {
                            Console.WriteLine($"  {line.Trim()}");
                        }
                    }
                }
            });
            // Also look for message children
            task.VisitAllChildren<Message>(m => {
                if (m.Text?.Contains("/reference") == true || m.Text?.Contains("Newtonsoft") == true) {
                    Console.WriteLine($"  MSG: {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
                }
            });
        }
    }
});

// Also check what the command line of the Csc task looks like via CscCommandLineArgs
Console.WriteLine();
Console.WriteLine("=== Csc task parameters (References) ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var project = "";
        var p = task.Parent;
        while (p != null) {
            if (p is Project proj) { project = proj.Name; break; }
            p = p.Parent;
        }
        if (project.Contains("Services")) {
            Console.WriteLine($"  Task children count: {task.Children.Count}");
            foreach (var child in task.Children) {
                var s = child.ToString();
                if (s.Length < 100) Console.WriteLine($"    {child.GetType().Name}: {s}");
            }
        }
    }
});

// Let's look at the project file text from embedded files
Console.WriteLine();
Console.WriteLine("=== Embedded files (project files) ===");
var archives = build.FindChild<NamedNode>("SourceFiles");
if (archives != null) {
    Console.WriteLine($"Found SourceFiles: {archives.Children.Count}");
}

// Try SourceFilesArchive
build.VisitAllChildren<NamedNode>(n => {
    if (n.Name?.Contains("Source") == true && n.Name?.Contains("File") == true) {
        Console.WriteLine($"  Found: {n.Name} ({n.GetType().Name}) children={n.Children?.Count}");
    }
});
